-- Make the About and Contact pages editable from the CMS.
--
-- Both pages were rebuilt with their copy written directly into the templates,
-- which meant none of it could be changed without editing PHP. This moves every
-- string into page_blocks so it appears under Content -> Page copy, and drops the
-- twelve orphaned About blocks left by the old template.

DELETE FROM `page_blocks` WHERE `page_key` = 'about';
DELETE FROM `page_blocks` WHERE `page_key` = 'contact' AND `block_key` IN ('heading', 'intro');

-- response_note predates this and sat in its own one-field group. It is the line
-- beside the submit button, so it belongs with the rest of the form.
UPDATE `page_blocks`
   SET `group_name` = 'Form', `label` = 'Note beside the button', `sort_order` = 14
 WHERE `page_key` = 'contact' AND `block_key` = 'response_note';

